#include <vector>
#include <algorithm>

class Solution {
    bool canPlace(const std::vector<int>& position, int m, int d) {
        int count = 1, last = position[0];
        for (size_t i = 1; i < position.size(); ++i) {
            if (position[i] - last >= d) {
                count++;
                last = position[i];
                if (count == m) return true;
            }
        }
        return false;
    }
public:
    int maxDistance(std::vector<int>& position, int m) {
        std::sort(position.begin(), position.end());
        int low = 1, high = position.back() - position.front(), ans = 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canPlace(position, m, mid)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    private boolean canPlace(int[] position, int m, int d) {
        int count = 1, last = position[0];
        for (int i = 1; i < position.length; i++) {
            if (position[i] - last >= d) {
                count++;
                last = position[i];
                if (count == m) return true;
            }
        }
        return false;
    }
    public int maxDistance(int[] position, int m) {
        Arrays.sort(position);
        int low = 1, high = position[position.length - 1] - position[0], ans = 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canPlace(position, m, mid)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
}

var maxDistance = function(position, m) {
    position.sort((a, b) => a - b);
    function canPlace(d) {
        let count = 1, last = position[0];
        for (let i = 1; i < position.length; i++) {
            if (position[i] - last >= d) {
                count++;
                last = position[i];
                if (count === m) return true;
            }
        }
        return false;
    }
    let low = 1, high = position[position.length - 1] - position[0], ans = 1;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        if (canPlace(mid)) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return ans;
};
